SELECT coalesce(json_agg("_root"), '[]') AS "_root" FROM (WITH "_root.base" AS (SELECT * FROM "cf_select"."items" WHERE "cf_select"."items"."id" = $1::int4) SELECT row_to_json((SELECT "_e" FROM (SELECT "cf_select"."item_label"("item" := ROW("_root.base"."id", "_root.base"."owner_id", "_root.base"."label", "_root.base"."amount", "_root.base"."payload")::"cf_select"."items") AS "item_label", "cf_select"."item_score"("item" := ROW("_root.base"."id", "_root.base"."owner_id", "_root.base"."label", "_root.base"."amount", "_root.base"."payload")::"cf_select"."items", "multiplier" := $2::"pg_catalog"."int4") AS "item_score", "cf_select"."item_second"("multiplier" := $3::"pg_catalog"."int4", "item" := ROW("_root.base"."id", "_root.base"."owner_id", "_root.base"."label", "_root.base"."amount", "_root.base"."payload")::"cf_select"."items") AS "item_second", ("cf_select"."item_payload"("item" := ROW("_root.base"."id", "_root.base"."owner_id", "_root.base"."label", "_root.base"."amount", "_root.base"."payload")::"cf_select"."items") #> $4::text[]) AS "item_payload") AS "_e")) AS "_root" FROM "_root.base") AS "_root"
